<?php
namespace App\Modules\Canteen\Services;
use Carbon\Carbon;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class Ordering {
 private static function subject(Request $r){$id=$r->attributes->get('canteen.target_user_id');return $id?\App\Models\User::find($id):$r->user();}
 public static function token(Request $r,int $company,array $quote):string {return hash_hmac('sha256',json_encode(['company'=>$company,'user'=>self::subject($r)?->id,'quote'=>$quote]),config('app.key'));}
 public static function consumption(int $company,int $user,string $zone):\Illuminate\Support\Collection {
  $local=now()->setTimezone($zone);$day=$local->copy()->startOfDay()->setTimezone(config('app.timezone'));$week=$local->copy()->startOfWeek()->setTimezone(config('app.timezone'));$month=$local->copy()->startOfMonth()->setTimezone(config('app.timezone'));$earliest=min($day,$week,$month);
  return DB::table('canteen_order_lines')->join('canteen_orders','canteen_orders.id','=','canteen_order_lines.order_id')->where('canteen_orders.company_id',$company)->where('canteen_orders.user_id',$user)->where('canteen_orders.status','!=','cancelled')->where('canteen_orders.created_at','>=',$earliest)->selectRaw('item_id,SUM(CASE WHEN canteen_orders.created_at >= ? THEN quantity ELSE 0 END) as day,SUM(CASE WHEN canteen_orders.created_at >= ? THEN quantity ELSE 0 END) as week,SUM(CASE WHEN canteen_orders.created_at >= ? THEN quantity ELSE 0 END) as month',[$day,$week,$month])->groupBy('item_id')->get()->keyBy('item_id');
 }
 public static function consumed(int $company,int $user,int $item,string $period,?string $zone=null):int {$zone??=DB::table('canteen_settings')->where('company_id',$company)->value('timezone')??'Asia/Karachi';$local=now()->setTimezone($zone);$start=(match($period){'week'=>$local->startOfWeek(),'month'=>$local->startOfMonth(),default=>$local->startOfDay()})->setTimezone(config('app.timezone'));return (int)DB::table('canteen_order_lines')->join('canteen_orders','canteen_orders.id','=','canteen_order_lines.order_id')->where('canteen_orders.company_id',$company)->where('canteen_orders.user_id',$user)->where('canteen_orders.status','!=','cancelled')->where('canteen_orders.created_at','>=',$start)->where('canteen_order_lines.item_id',$item)->sum('quantity');}
 public static function quote(Request $r,int $company,array $selections,bool $lock=false):array {
  CanteenAccess::company($r,$company);$subject=self::subject($r);abort_unless($subject,422,'Sign in with an employee account to place an order.');$query=DB::table('canteen_profiles')->where('company_id',$company)->where('user_id',$subject->id);if($lock)$query->lockForUpdate();$profile=$query->first();abort_unless($profile&&$profile->eligible&&$profile->level_id,422,'Your Canteen benefit level and eligibility must be assigned first.');$level=DB::table('canteen_levels')->where('id',$profile->level_id)->where('company_id',$company)->where('active',true)->first();abort_unless($level,422,'Your benefit level is inactive.');$settings=DB::table('canteen_settings')->where('company_id',$company)->first();abort_unless($settings&&$settings->ordering_enabled&&$settings->within_allowance_mode,422,'Ordering is not enabled for this company.');$lines=[];$gross=0;$subsidy=0;
  foreach($selections as $s){$itemQuery=DB::table('canteen_items')->where('id',$s['item_id'])->where('company_id',$company);if($lock)$itemQuery->lockForUpdate();$item=$itemQuery->first();abort_unless($item&&$item->active,422,'An item is unavailable.');$category=DB::table('canteen_categories')->where('id',$item->category_id)->where('active',true)->first();abort_unless($category,422,'An item category is unavailable.');$time=now()->setTimezone($settings->timezone)->format('H:i:s');abort_if(($item->available_from&&$time<$item->available_from)||($item->available_to&&$time>$item->available_to),422,'An item is outside its availability schedule.');$rule=DB::table('canteen_item_rules')->where('item_id',$item->id)->where('level_id',$level->id)->first();abort_unless($rule,422,'An item is not eligible for your level.');$qty=(int)$s['quantity'];abort_if($item->stock_enabled&&$item->stock_quantity<$qty,422,'Insufficient stock for '.$item->name.'.');$used=self::consumed($company,$profile->user_id,$item->id,$rule->period,$settings->timezone);$within=$rule->quantity_limit===null?$qty:min($qty,max(0,$rule->quantity_limit-$used));$excess=$qty-$within;abort_if($excess&&$settings->excess_mode==='block',422,'Your allowance has been reached.');$cents=(int)round((float)$item->price*100);$percent=$rule->company_percent??$level->company_percent;$unitSubsidy=(int)round($cents*$percent/100);$companyCents=$within*($settings->within_allowance_mode==='free'?$cents:$unitSubsidy)+$excess*($settings->excess_mode==='level_share'?$unitSubsidy:0);$lineGross=$cents*$qty;$gross+=$lineGross;$subsidy+=$companyCents;$lines[]=['stock_tracked'=>(bool)$item->stock_enabled,'item_id'=>$item->id,'item_name'=>$item->name,'category_id'=>$category->id,'category_name'=>$category->name,'quantity'=>$qty,'unit_price'=>$cents/100,'gross'=>$lineGross/100,'company_share'=>$companyCents/100,'employee_share'=>($lineGross-$companyCents)/100,'allowance_quantity'=>$within,'period'=>$rule->period];}
  return ['level_id'=>$level->id,'level_name'=>$level->name,'lines'=>$lines,'gross'=>$gross/100,'company_share'=>$subsidy/100,'employee_share'=>($gross-$subsidy)/100];
 }
}
